  requireSafe(['RESERVED','PRE_CONNECTION'].includes(lease.phase) ? lease.boundBackend === null : lease.phase === 'FAILED_OR_UNKNOWN' && lease.boundBackend === null || validBackend(lease.boundBackend, lease));
