import { lstat, open, readdir } from 'node:fs/promises';
import { constants } from 'node:fs';
import { resolve, join, dirname, parse, isAbsolute } from 'node:path';
const fail = () => { throw new Error('QUIESCENCE_NOT_PROVEN'); };
